import { action, createEffect, createRoot, createTrackedEffect } from "solid-js";

export const runStep = (cb) => {
  void action(function* () {
    cb();
  })();
};
export const runStepWith = (o) => {
  void action(function* () {
    o.run();
  })();
};
export const runStepAll = (fns) => {
  void action(function* () {
    for (const f of fns) f();
  })();
};
export const StepView = (props) => {
  queueMicrotask(() => {
    void action(function* () {
    props.render?.();
    if (typeof props.children === "function") props.children();
  })();
  });
  return null;
};
export const runApply = (cb) => {
  createRoot(() => {
    createEffect(() => 1, () => {
      cb();
    });
  });
};
export const runApplyWith = (o) => {
  createRoot(() => {
    createEffect(() => 1, () => {
      o.run();
    });
  });
};
export const runApplyAll = (fns) => {
  createRoot(() => {
    createEffect(() => 1, () => {
      for (const f of fns) f();
    });
  });
};
export const ApplyView = (props) => {
  queueMicrotask(() => {
    createRoot(() => {
    createEffect(() => 1, () => {
      props.render?.();
    if (typeof props.children === "function") props.children();
    });
  });
  });
  return null;
};
export const runLeaf = (cb) => {
  createRoot(() => {
    createTrackedEffect(() => {
      cb();
    });
  });
};
export const runLeafWith = (o) => {
  createRoot(() => {
    createTrackedEffect(() => {
      o.run();
    });
  });
};
export const runLeafAll = (fns) => {
  createRoot(() => {
    createTrackedEffect(() => {
      for (const f of fns) f();
    });
  });
};
export const LeafView = (props) => {
  queueMicrotask(() => {
    createRoot(() => {
    createTrackedEffect(() => {
      props.render?.();
    if (typeof props.children === "function") props.children();
    });
  });
  });
  return null;
};
export const skipRun = (cb) => { void cb; };
export const skipRunWith = (o) => { void o; };
export const skipRunAll = (fns) => { void fns; };
export const SkipView = (props) => { void props; return null; };
